style.css:
@-moz-document url-prefix("https://chat.google.com/") {
/* 1. Soft Pastel Pink Background */
  body, 
  .k5pkwc, 
  .ZIeecf, 
  [role="main"] {
    background-color: #fff0f3 !important;
    background-image: linear-gradient(135deg, #ffe5ec 0%, #ffccd5 100%) !important;
  }

  /* 2. Clean, Translucent White Panels & Sidebars */
  .T2L3nd, 
  .fGxEDd, 
  .Wic03c,
  div[jsname="V67aGc"] {
    background-color: rgba(255, 255, 255, 0.8) !important;
    backdrop-filter: blur(12px) !important;
    border-right: 1px solid rgba(255, 182, 193, 0.4) !important;
  }

  /* 3. Text Contrast & Readability */
  .nsvEvb, 
  div[role="textbox"] {
    color: #4a353c !important;
  }

  /* 4. Elegant Pink Chat Bubbles */
  .TqwGTe, 
  .oJeWuf {
    background-color: rgba(255, 192, 203, 0.6) !important;
    backdrop-filter: blur(8px);
    border-radius: 18px !important;
    border: 1px solid rgba(255, 160, 180, 0.4) !important;
  }
}
